const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions - Shebelle River area in Somalia
  const shebelleRiver = ee.Geometry.Point([45.3, 2.0]).buffer(5000); // ~10km diameter area

  const date2018 = '2018-05-09';
  const date2015 = '2015-05-17';

  // 2. Data Acquisition - Sentinel-1 SAR for water detection
  const col2018 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(shebelleRiver)
    .filterDate(date2018, ee.Date(date2018).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const col2015 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(shebelleRiver)
    .filterDate(date2015, ee.Date(date2015).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const size2018 = col2018.size().getInfo();
  const size2015 = col2015.size().getInfo();

  console.log(`2018 Images: ${size2018}`);
  console.log(`2015 Images: ${size2015}`);

  // Check for missing data - try wider date range if needed
  if (size2018 === 0 || size2015 === 0) {
    // Try 3-day window
    const col2018_wider = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(shebelleRiver)
      .filterDate(ee.Date(date2018).advance(-1, 'day'), ee.Date(date2018).advance(2, 'day'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV');

    const col2015_wider = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(shebelleRiver)
      .filterDate(ee.Date(date2015).advance(-1, 'day'), ee.Date(date2015).advance(2, 'day'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV');

    const size2018_w = col2018_wider.size().getInfo();
    const size2015_w = col2015_wider.size().getInfo();

    console.log(`Wider search - 2018: ${size2018_w}, 2015: ${size2015_w}`);

    if (size2018_w === 0 || size2015_w === 0) {
      console.log('No data found even with wider date range');
      console.log('<answer>C1</answer>');
      return;
    }

    var img2018 = col2018_wider.first();
    var img2015 = col2015_wider.first();
  } else {
    var img2018 = col2018.first();
    var img2015 = col2015.first();
  }

  // 3. Processing - Calculate backscatter statistics
  const stats2018 = img2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: shebelleRiver,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2015 = img2015.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: shebelleRiver,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean2018 = stats2018.get('VV_mean').getInfo();
  const count2018 = stats2018.get('VV_count').getInfo();
  const mean2015 = stats2015.get('VV_mean').getInfo();
  const count2015 = stats2015.get('VV_count').getInfo();

  console.log(`2018: Mean=${mean2018}, Pixels=${count2018}`);
  console.log(`2015: Mean=${mean2015}, Pixels=${count2015}`);

  // 4. Validation
  if (count2018 === 0 || count2015 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean2018 === null || mean2015 === null || isNaN(mean2018) || isNaN(mean2015)) {
    console.log('Invalid calculation results');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if values are in valid SAR range
  if (mean2018 < -35 || mean2018 > 10 || mean2015 < -35 || mean2015 > 10) {
    console.log('Values outside valid SAR range');
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Final Answer - Lower backscatter = more water = higher level
  const diff = mean2018 - mean2015;
  console.log(`Backscatter difference (2018-2015): ${diff.toFixed(2)} dB`);

  if (mean2018 < mean2015) {
    console.log('2018 had lower backscatter = higher water levels');
    console.log('<answer>A</answer>');
  } else {
    console.log('2018 had higher/equal backscatter = lower/equal water levels');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
